def clamp_list(xs, lo, hi):
    smallest, largest = (min(xs), max(xs))
    if lo <= smallest and largest <= hi:
        return list(xs)
    if largest <= lo:
        return [lo] * len(xs)
    if smallest >= hi:
        return [hi] * len(xs)
    return [lo if x < lo else hi if x > hi else x for x in xs]
```

